import os
import sqlite3
from flask import Flask, request, g, jsonify

app = Flask(__name__)
app.secret_key = os.environ.get("APP_SECRET", "dev-secret-key")

DATABASE = "db.sqlite3"


def get_db():
    db = getattr(g, "_database", None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db


@app.teardown_appcontext
def close_db(exception):
    db = getattr(g, "_database", None)
    if db is not None:
        db.close()


def init_db():
    conn = sqlite3.connect(DATABASE)
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS messages (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL,
                content TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
            """
        )
        conn.commit()
    finally:
        conn.close()


@app.route("/messages", methods=["GET"])
def get_messages():
    try:
        limit = int(request.args.get("limit", 10))
        offset = int(request.args.get("offset", 0))
        sort = request.args.get("sort", "desc").upper()
    except ValueError:
        return jsonify({"error": "limit and offset must be integers"}), 400

    if sort not in ("ASC", "DESC"):
        sort = "DESC"

    conn = get_db()
    cur = conn.execute(
        "SELECT id, username, content, created_at FROM messages ORDER BY created_at ? LIMIT ? OFFSET ?",
        (sort, limit, offset),
    )
    rows = cur.fetchall()
    conn.close()

    messages = [
        {
            "id": row["id"],
            "username": row["username"],
            "content": row["content"],
            "created_at": row["created_at"],
        }
        for row in rows
    ]
    return jsonify(messages)


@app.route("/messages", methods=["POST"])
def post_message():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "Invalid JSON body"}), 400

    username = data.get("username")
    content = data.get("content")

    if not isinstance(username, str) or not username.strip():
        return jsonify({"error": "'username' must be a non-empty string"}), 400
    if not isinstance(content, str) or not content.strip():
        return jsonify({"error": "'content' must be a non-empty string"}), 400

    conn = get_db()
    cur = conn.execute(
        "INSERT INTO messages (username, content) VALUES (?, ?)",
        (username.strip(), content.strip()),
    )
    conn.commit()
    msg_id = cur.lastrowid
    conn.close()

    return jsonify({"id": msg_id, "username": username, "content": content}), 200


init_db()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
